class Command(BaseCommand):
    help = "Add Coding, Technical, HR interview and Projects topics with practice questions and topic tasks."

    def handle(self, *args, **opts):
        tracking.SILENT = True  # loading lessons in bulk should not notify students
        try:
            self._run()
        finally:
            tracking.SILENT = False

    def _run(self):
        admin = User.objects.filter(role=Role.ADMIN, is_active=True).order_by("id").first()
        made = qn = 0
        for n, (section, title, notes, ttype, prompt, options, questions) in enumerate(LESSONS):
            g = Guide.objects.filter(area="JOB_PREP", section=section, title=title).first()
            if not g:
                g = Guide.objects.create(area="JOB_PREP", section=section, kind="NOTES", title=title, body=notes, order_no=200 + n, uploaded_by=admin)
                GuideTaskSetting.objects.create(guide=g, task_type=ttype, prompt=prompt, options=options)
                made += 1
            have = set(GuideQuestion.objects.filter(guide=g).values_list("text", flat=True))
            i = len(have)
            for text, o, correct, why in questions:
                if text in have:
                    continue
                # many questions were written with the right answer first; mix the options (the same way every run)
                order = list(range(4))
                random.Random(text).shuffle(order)
                o, correct = [o[k] for k in order], order.index(correct)
                GuideQuestion.objects.create(guide=g, qtype="MCQ", text=text, option_a=o[0], option_b=o[1], option_c=o[2], option_d=o[3], correct=correct, explanation=why, order_no=i)
                i += 1
                qn += 1
        self.stdout.write(self.style.SUCCESS(f"Done. Added {made} lessons and {qn} practice questions."))
